import{_ as p,a0 as t,w as r,s as o,I as n,x as a,a1 as i,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"YAML 使用入門 | LCTT x X-CMD","titleTemplate":false,"description":"YAML 使用入門 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"YAML 使用入門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"YAML 使用入門 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210917 Start using YAML now","title":"YAML 使用入門","tag":"202109","desc":""},"relativePath":"202109/20210917 Start using YAML now.md","filePath":"[post].md"}'),u={name:"202109/20210917 Start using YAML now.md"};function g(h,s,m,k,b,f){const l=t("Link");return r(),o("div",null,[s[25]||(s[25]=n("h1",{id:"yaml-使用入門",tabindex:"-1"},[a("YAML 使用入門 "),n("a",{class:"header-anchor",href:"#yaml-使用入門","aria-label":"Permalink to “YAML 使用入門”"},"​")],-1)),s[26]||(s[26]=n("blockquote",null,[n("p",null,"什麼是 YAML，為什麼我們現在應該開始使用它？")],-1)),s[27]||(s[27]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/23/095242fw0qzzp5fe6e565z.jpg",alt:""})],-1)),n("p",null,[i(l,{href:"https://yaml.org/"},{default:e(()=>[...s[0]||(s[0]=[a("YAML",-1)])]),_:1}),s[1]||(s[1]=a("（",-1)),s[2]||(s[2]=n("ruby",null,[a("YAML 不是標記語言"),n("rt",null,"YAML Ain't Markup Language")],-1)),s[3]||(s[3]=a("）是一種適宜閲讀理解的數據序列化語言。它的語法簡單而易於閲讀。它不包含引號、打開和關閉的標籤或大括號。它不包含任何可能使人類難以解析嵌套規則的東西。你可以看一下你的 YAML 文檔就知道它在什麼。",-1))]),s[28]||(s[28]=d(`<h3 id="yaml-特性" tabindex="-1">YAML 特性 <a class="header-anchor" href="#yaml-特性" aria-label="Permalink to “YAML 特性”">​</a></h3><p>YAML 有一些超級特性，使其優於其他序列化格式：</p><ul><li>易於略讀。</li><li>易於使用。</li><li>可在編程語言之間移植。</li><li>敏捷語言的原生數據結構。</li><li>支持通用工具的一致模型。</li><li>支持一次性處理。</li><li>表現力和可擴展性。</li></ul><p>我將通過一些例子進一步向你展示 YAML 的強大。</p><p>你能弄清楚下面發生了什麼嗎？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------</span></span>
<span class="line"><span># My grocery list</span></span>
<span class="line"><span>groceries:</span></span>
<span class="line"><span>    - Milk</span></span>
<span class="line"><span>    - Eggs</span></span>
<span class="line"><span>    - Bread</span></span>
<span class="line"><span>    - Butter</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>上面的例子包含了一個簡單的雜貨購物清單，它是一個完全格式化的 YAML 文檔。在 YAML 中，字符串不加引號，而列表需要簡單的連字符和空格。一個 YAML 文檔以 <code>---</code> 開始，以 <code>...</code> 結束，但它們是可選的。YAML中的註釋以 <code>#</code> 開始。</p><p>縮進是 YAML 的關鍵。縮進必須包含空格，而不是製表符。雖然所需的空格數量是靈活的，但保持一致是個好主意。</p><h3 id="基本元素" tabindex="-1">基本元素 <a class="header-anchor" href="#基本元素" aria-label="Permalink to “基本元素”">​</a></h3><h4 id="集合" tabindex="-1">集合 <a class="header-anchor" href="#集合" aria-label="Permalink to “集合”">​</a></h4><p>YAML 有兩種類型的集合。列表（用於序列）和字典（用於映射）。列表是鍵值對，每個值都在一個新的行中，以連字符和空格開始。字典也是鍵值對，每個值都是一個映射，包含一個鍵、一個冒號和空格以及一個值。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># My List</span></span>
<span class="line"><span>groceries:</span></span>
<span class="line"><span>    - Milk</span></span>
<span class="line"><span>    - Eggs</span></span>
<span class="line"><span>    - Bread</span></span>
<span class="line"><span>    - Butter</span></span>
<span class="line"><span></span></span>
<span class="line"><span># My dictionary</span></span>
<span class="line"><span>contact:</span></span>
<span class="line"><span>    name: Ayush Sharma</span></span>
<span class="line"><span>    email: myemail@example.com</span></span></code></pre></div><p>列表和字典經常被結合起來，以提供更復雜的數據結構。列表可以包含字典，而字典可以包含列表。</p><h4 id="字符串" tabindex="-1">字符串 <a class="header-anchor" href="#字符串" aria-label="Permalink to “字符串”">​</a></h4><p>YAML 中的字符串不需要加引號。多行字符串可以用 <code>|</code> 或 <code>&gt;</code> 來定義。前者保留了換行符，而後者則沒有。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_string: |</span></span>
<span class="line"><span>    This is my string.</span></span>
<span class="line"><span>    It can contain many lines.</span></span>
<span class="line"><span>    Newlines are preserved.</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_string_2: &gt;</span></span>
<span class="line"><span>    This is my string.</span></span>
<span class="line"><span>    This can also contain many lines.</span></span>
<span class="line"><span>    Newlines aren&#39;t preserved and all lines are folded.</span></span></code></pre></div><h4 id="錨點" tabindex="-1">錨點 <a class="header-anchor" href="#錨點" aria-label="Permalink to “錨點”">​</a></h4><p>YAML 可以通過節點錨點來獲得可重複的數據塊。<code>&amp;</code> 字符定義了一個數據塊，以後可以用 <code>*</code> 來引用。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>billing_address: &amp;add1</span></span>
<span class="line"><span>    house: B1</span></span>
<span class="line"><span>    street: My Street</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shipping_address: *add1</span></span></code></pre></div>`,22)),n("p",null,[s[5]||(s[5]=a("至止你對 YAML 的瞭解就足以讓你開始工作了。你可以使用在線 YAML 解析器來測試。如果你每天都與 YAML 打交道，那麼 ",-1)),i(l,{href:"https://yaml.org/refcard.html"},{default:e(()=>[...s[4]||(s[4]=[a("這個方便的備忘單",-1)])]),_:1}),s[6]||(s[6]=a(" 會對你有所幫助。",-1))]),n("p",null,[n("em",null,[s[8]||(s[8]=a("這篇文章最初發表在",-1)),i(l,{href:"https://notes.ayushsharma.in/2021/08/introduction-to-yaml"},{default:e(()=>[...s[7]||(s[7]=[a("作者的個人Blog",-1)])]),_:1}),s[9]||(s[9]=a("上，並經授權改編。",-1))])]),s[29]||(s[29]=n("hr",null,null,-1)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),i(l,{href:"https://opensource.com/article/21/9/intro-yaml"},{default:e(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/21/9/intro-yaml",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),i(l,{href:"https://opensource.com/users/ayushsharma"},{default:e(()=>[...s[12]||(s[12]=[a("Ayush Sharma",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),i(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:e(()=>[...s[14]||(s[14]=[a("geekpi",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:e(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const A=p(u,[["render",g]]);export{M as __pageData,A as default};
